func:
if (msg.statusCode !== undefined && msg.statusCode !== 200) {
  node.error(`CelesTrak respondió con HTTP ${msg.statusCode} para el grupo ${msg.group}`, msg);
  return null;
}

if (!Array.isArray(msg.payload)) {
  node.warn(`CelesTrak no devolvió una lista para el grupo ${msg.group}: ${String(msg.payload).slice(0, 200)}`);
  return null;
}

const group = msg.group || "stations";
const now = new Date().toISOString();

msg.payload = msg.payload
  .filter(o => o && o.NORAD_CAT_ID !== undefined)
  .map(o => ({
    key: String(o.NORAD_CAT_ID),
    value: JSON.stringify({
      schema_version: "1.0",
      norad_id: String(o.NORAD_CAT_ID),
      name: o.OBJECT_NAME,
      epoch: o.EPOCH,
      source: "celestrak:gp",
      group,
      ingested_at: now,
      omm: o
    })
  }));

node.status({ text: `${group}: ${msg.payload.length} satélites` });
return msg;

let raw = msg.payload;
if (raw && typeof raw === "object" && raw.value !== undefined) raw = raw.value;
if (Buffer.isBuffer(raw)) raw = raw.toString("utf8");

let data;
try { data = typeof raw === "string" ? JSON.parse(raw) : raw; }
catch (e) { return null; }
if (!data || ![data.lat, data.lon].every(Number.isFinite)) return null;

// Discard data from earlier
const max_age_ms = 30000;
const age = Date.now() - Date.parse(data.ts);
if(!Number.isFinite(age) || age > max_age_ms) return null;

const groups = Array.isArray(data.groups) && data.groups.length ? data.groups : ["sin grupo"];
const group = groups[0];
const norad = String(data.norad_id);
const name = data.name || norad;
const alt = Number.isFinite(data.alt_km) ? Math.round(data.alt_km) + " km" : "n/d";
const vel = Number.isFinite(data.velocity_kms) ? data.velocity_kms.toFixed(2) + " km/s" : "n/d";

const botones = /^[0-9]+$/.test(norad)
  ? `<br><button onclick='feedback("${norad}","${norad}","track_on",true)'>Predecir próxima órbita</button>`
    + ` <button onclick='feedback("${norad}","${norad}","track_off",true)'>Quitar</button>`
  : "";

msg.topic = norad;                       // lo usa el limitador por satélite
msg.payload = {
  name: `${name} (${norad})`,            // identificador único del marcador
  lat: data.lat,
  lon: data.lon,
  icon: "satellite",
  iconColor: "#4a6680",
  layer: group,                          // una capa por grupo: se activan desde el menú de capas
  tooltip: name,                         // el nombre solo al pasar el ratón
  ttl: 30,
  popup: `<b>${escapeHtml(name)}</b><br>NORAD ${norad}`
       + `<br>grupos: ${groups.map(escapeHtml).join(", ")}`
       + `<br>alt: ${alt}<br>vel: ${vel}${botones}`
};
return msg;

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

msg.key = msg.payload.key;
msg.payload = msg.payload.value;
return msg;

let raw = msg.payload;
if (raw && typeof raw === "object" && raw.value !== undefined) raw = raw.value;
if (Buffer.isBuffer(raw)) raw = raw.toString("utf8");
let data;
try { data = typeof raw === "string" ? JSON.parse(raw) : raw; }
catch { node.warn("Globo: posición no válida"); return null; }
if (!data || !/^[0-9]+$/.test(String(data.norad_id)) ||
    ![data.lat, data.lon, data.alt_km].every(Number.isFinite) ||
    Math.abs(data.lat) > 90 || Math.abs(data.lon) > 180 || data.alt_km < 0 ||
    typeof data.ts !== "string" || !Number.isFinite(Date.parse(data.ts))) {
    node.warn("Globo: posición incompleta o fuera de rango");
    return null;
}
return {
    payload: JSON.stringify({
        norad_id: String(data.norad_id),
        name: typeof data.name === "string" ? data.name : String(data.norad_id),
        groups: Array.isArray(data.groups) ? data.groups.filter(g => typeof g === "string") : [],
        lat: data.lat, lon: data.lon, alt_km: data.alt_km, ts: data.ts,
        velocity_kms: Number.isFinite(data.velocity_kms) && data.velocity_kms >= 0 ? data.velocity_kms : null
    })
};

// Mensajes del globo: {"type":"track_on"|"track_off","norad_id":"25544"}
let req;
try { req = JSON.parse(msg.payload); } catch (e) { return null; }
const session = msg._session;
if (!session || !req || typeof req.type !== "string") return null;

const subs = flow.get("trackSubs") || {};
const key = "globe:" + session.id;

if (req.type === "track_off") {
    delete subs[key];
    flow.set("trackSubs", subs);
    return null;
}
const norad = String(req.norad_id);
if (req.type !== "track_on" || !/^[0-9]{1,9}$/.test(norad)) return null;

const isNew = !subs[key] || subs[key].norad !== norad;

// track_on llega al activar y luego cada 30 s como latido: renueva la caducidad.
subs[key] = { kind: "globe", session, norad, expires: Date.now() + 90000 };
flow.set("trackSubs", subs);
return { key: norad, payload: JSON.stringify({ norad_id: norad, requested_at: new Date().toISOString(), force: isNew }) };

// Eventos del worldmap: feedback(..., "track_on"/"track_off") y "disconnect".
// Salida 1 (arriba): órdenes al mapa (borrar la línea anterior).
// Salida 2 (abajo): peticiones a Kafka (satellites.track.request).
const p = msg.payload || {};
const sessionId = msg._sessionid;
if (!sessionId) return null;

const subs = flow.get("trackSubs") || {};
const key = "map:" + sessionId;
const previous = subs[key];
const removePrevious = previous
    ? { _sessionid: sessionId, payload: { name: "track-" + previous.norad, deleted: true } }
    : null;

if (p.action === "disconnect") {        // pestaña cerrada: dejar de enviarle
    delete subs[key];
    flow.set("trackSubs", subs);
    return null;
}
if (p.action !== "track_on" && p.action !== "track_off") return null;

if (p.action === "track_off") {
    delete subs[key];
    flow.set("trackSubs", subs);
    return [removePrevious, null];
}
const norad = String(p.value);
if (!/^[0-9]{1,9}$/.test(norad)) return null;

// El mapa no tiene latido: la suscripción dura hasta "Quitar" o hasta cerrar la pestaña.
subs[key] = { kind: "map", session: sessionId, norad, expires: null };
flow.set("trackSubs", subs);
const request = { key: norad, payload: JSON.stringify({ norad_id: norad, requested_at: new Date().toISOString(), force: true }) };
return [previous && previous.norad !== norad ? removePrevious : null, request];

// Purga suscripciones caducadas y renueva el lease del propagador:
// una sola petición por NORAD distinto, aunque lo miren muchas sesiones.
const subs = flow.get("trackSubs") || {};
const now = Date.now();
const norads = new Set();
for (const [key, sub] of Object.entries(subs)) {
    if (sub.expires !== null && sub.expires < now) delete subs[key];
    else norads.add(sub.norad);
}
flow.set("trackSubs", subs);
const requestedAt = new Date().toISOString();
return [[...norads].map(n => ({ key: n, payload: JSON.stringify({ norad_id: n, requested_at: requestedAt }) }))];

let raw = msg.payload;
if (raw && typeof raw === "object" && raw.value !== undefined) raw = raw.value;
if (Buffer.isBuffer(raw)) raw = raw.toString("utf8");
let track;
try { track = typeof raw === "string" ? JSON.parse(raw) : raw; } catch (e) { return null; }
if (!track || !/^[0-9]+$/.test(String(track.norad_id)) ||
    !Array.isArray(track.points) || track.points.length < 2) return null;

const norad = String(track.norad_id);
const subs = flow.get("trackSubs") || {};
const now = Date.now();
const toGlobe = [];
const toMap = [];
let globePayload = null;   // se calcula una sola vez, aunque haya varias pestañas del globo

for (const sub of Object.values(subs)) {
    if (sub.norad !== norad || (sub.expires !== null && sub.expires < now)) continue;
    if (sub.kind === "globe") {
        // El globo dibuja la órbita en el espacio; el mapa 2D, la traza sobre el terreno.
        globePayload = globePayload ||
            JSON.stringify({ type: "track", ...track, points: toInertial(track), frame: "inertial" });
        toGlobe.push({ _session: sub.session, payload: globePayload });
    } else {
        toMap.push({ _sessionid: sub.session, payload: {
            name: "track-" + norad,
            line: splitAtAntimeridian(track.points),
            color: "#ff2d55", weight: 3, opacity: 1,
            layer: "Predicción",
            clickable: true,
            popup: "Próxima órbita · " + escapeHtml(track.name || norad) + " (NORAD " + norad + ")"
        }});
    }
}
return [toGlobe, toMap];

// Traza sobre el terreno -> órbita en el espacio, con la Tierra "congelada" en el primer punto.
// Cada punto se gira alrededor del eje terrestre lo que la Tierra ha girado desde el inicio:
// solo cambia la longitud. Comparado con el cálculo exacto en el propagador, el error es de
// pocos km (2 km en la ISS, 13 km en un Galileo), invisible a la escala del globo.
function toInertial(t) {
    if (t.frame === "inertial") return t.points;            // ya viene convertida del propagador
    const EARTH_DEG_PER_S = 360.98564736629 / 86400;        // giro de la Tierra (día sidéreo)
    const step = Number(t.step_s) || 60;
    return t.points.map(([lat, lon, alt], k) => {
        const l = ((lon + EARTH_DEG_PER_S * step * k + 540) % 360) - 180;
        return [lat, Math.round(l * 1e4) / 1e4, alt];
    });
}

// Parte la línea al cruzar ±180°: si no, Leaflet une +179° con -179° cruzando todo el mapa.
function splitAtAntimeridian(points) {
    const segments = [[]];
    for (let i = 0; i < points.length; i++) {
        const [lat, lon] = points[i];
        if (i > 0) {
            const [plat, plon] = points[i - 1];
            if (Math.abs(lon - plon) > 180) {
                const edge = plon > 0 ? 180 : -180;
                const lonUnwrapped = lon + (plon > 0 ? 360 : -360);
                const f = (edge - plon) / (lonUnwrapped - plon);   // dónde cae el cruce (0..1)
                const latCross = plat + f * (lat - plat);
                segments[segments.length - 1].push([latCross, edge]);   // cierra en un borde
                segments.push([[latCross, -edge]]);                     // reabre en el otro
            }
        }
        segments[segments.length - 1].push([lat, lon]);
    }
    return segments;
}

function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

// Mapa 2D con un solo mundo. Las capas base de Worldmap se repiten en horizontal sin fin, y
// los marcadores y la traza de predicción solo se dibujan en una de las copias. Esta capa usa
// noWrap: Leaflet dibuja el mundo una vez y fuera de ±180° queda fondo vacío, así que se puede
// alejar el zoom libremente sin ver copias.
const p = msg.payload || {};
if (p.action !== "connected" || !msg._sessionid) return null;

const LAYER = "OSM (un solo mundo)";
const sid = msg._sessionid;

// 1) Pasar antes a una capa propia de Worldmap. Si la pestaña se reconecta y ya tenía la nuestra,
//    así se quita del mapa la copia antigua en lugar de apilar otra encima.
const toBuiltIn = { _sessionid: sid, payload: { command: { layer: "OSM" } } };

// 2) Crear la capa sin repetición y activarla. zoomLevels vacío quita límites de zoom anteriores.
const toSingleWorld = { _sessionid: sid, payload: { command: {
    map: {
        name: LAYER,
        url: "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
        opt: {
            noWrap: true,                                  // no repetir el mundo
            bounds: [[-85.0511, -180], [85.0511, 180]],    // no pedir teselas fuera de él
            subdomains: ["a", "b", "c"],
            maxNativeZoom: 19,
            maxZoom: 20,
            attribution: "Map data © OpenStreetMap contributors"
        }
    },
    layer: LAYER,
    zoomLevels: []
} } };


const fitWorld = {
    _sessionid: sid, payload: {
        command: {
            bounds: [[-60, -180], [75, 180]]
        }
    }
};

return [[toBuiltIn, toSingleWorld]];
